      expect(parsed.kind).toBeDefined();
      expect(parsed.timestamp).toBeDefined();
      expect(parsed.stateHash).toMatch(/^sha256:[0-9a-f]{64}$/);
    }
  });

90→  it("prevents UI freezing and visual clipping on large traces (Acceptance Criteria)", () => {
