// restaurant-game.ts (end of file, add these methods)
import { z } from 'zod';
import fs from 'fs';
import path from 'path';
import { v4 as uuid } from 'uuid';

const ArenaTraceV3 = z.object({
  version: z.literal('restaurant 3'),
  arenaId: z.string().regex(/^[a-z0-9]{8}-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{12}$/),
  sessionId: z.string .optional(),
  seed: z.number(),
  replay: z.object({
    variation: z.string().optional(),
    inputs: z.array(z.object({
      tick: z.number(),
      round: z.number(),
      action: z.any(),
      stateHash: z.string(),
      restaurantStateHash: z.string(). optional(),
    })),
    finalStateHash: z.string(),
    finalRestaurantStateHash: z.string().optional(),
    status: z.enum(['ok', 'timeout', 'error']),
    tick: z.number(),
    reason: z.string(),
  }),
  initialState: z.record(z.any()),
  events: z .array(z.any()),
  terminal: z.object({
    status: z.enum(['ok', 'timeout', 'error']),
    tick: z.number(),
    reason: z.string(),
  }),
});

export type RestaurantArenaTraceV3 = z.infer<typeof ArenaTraceV3>;

export function captureArenaTrace(game: RestaurantGame, options: {
  runKind: 'live' | 'synthetic' | 'benchmark';
  additionalEvents?: TraceV3Event[];
}) : RestaurantArenaTraceV3 {
  const { runKind, additionalEvents = [] } = options;
  const initialState = game.getInitialState();
  const events = [...game.getRecordedEvents(), ...additionalEvents];
  const replay = game.getReplayRecord();
  const terminal = game.getTerminalStatus();
  const trace = {
    version: 'restaurant 3',
    arenaId: game.state().episode.id,
    sessionId: game.state().episode.id,
 seed: game.state().seed,
    replay,
    initialState,
    events,
    terminal,
  };
  return ArenaTraceV3.parse(trace);
}

export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
  return JSON.stringify(trace, null, 2);
}

export function exportTraceJson (trace: RestaurantArenaTraceV3): string {
  return JSON.stringify(trace, null, 2);
}

export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const header = {
    version: trace.version,
    replay: trace.replay,
  };
  return [JSON.stringify (header), ...trace.events.map(e => JSON.stringify(e))].join('\n');
}

export function validateArenaTraceV3(trace: unknown): { valid: boolean; errors: string[] } {
  try {
    ArenaTraceV3.parse(trace);
    return { valid: true, errors: [] };
  } catch (e) {
    const errors = (e as any).errors?.map((err: any) => `${err.path.join('.')} : ${err.message}`) || [];
    return { valid: false, errors };
  }
}

export function replayArenaTrace(trace: RestaurantArenaTraceV3): Restaurant Game {
  const game = new RestaurantGame(trace.seed, trace.replay.variation);
  const initialState = game.getInitialState();
  const traceInitial = trace.initialState;
  const canonicalInitial = canonicalizeWorkerRole(initialState);
  const canonicalTraceInitial = canonicalizeWorkerRole(traceInitial);
  if (JSON.stringify(canonicalInitial) !== JSON.stringify(canonicalTraceInitial)) {
    throw new Error('Initial state mismatch');
  }
  for (const input of trace.replay.inputs) {
    game.applyArenaReplayInput(input);
    const stateHash = game.computeStateHash();
    if (stateHash !== input .stateHash) {
      throw new Error(`Checkpoint mismatch at tick ${input.tick}`);
    }
    if (input.restaurantStateHash) {
      const restaurantHash = game.computeStateHash();
      if (restaurantHash !== input.restaurantStateHash) {
        throw new Error(`Restaurant state hash mismatch at tick ${input.tick}`);
      }
    }
  }
  const finalStateHash = game.computeStateHash();
  if (finalStateHash !== trace.replay.finalStateHash) {
    throw new Error('Final state hash mismatch');
  }
  if (trace.replay.finalRestaurantStateHash) {
    const finalRestaurant = game.computeStateHash();
    if (finalRestaurant !== trace.replay.finalRestaurantStateHash) {
      throw new Error('Final restaurant state hash mismatch');
    }
  }
  const terminal = game.getTerminalStatus();
  if (terminal.status !== trace.terminal.status || terminal.tick !== trace.terminal.tick || terminal.reason !== trace.terminal.reason) {
    throw new Error('Terminal outcome mismatch');
  }
  return game;
}

function canonicalizeWorkerRole(state: any): any {
  if (!state.workers) return state;
  return {
    ...state,
    workers: state.workers.map((w: any) => ({
 ...w,
      role: w.role === 'expediter' ? 'supply_lead' : w.role,
      id: w.id === 'worker-expediter' ? 'worker-supply_lead' : w.id,
    })),
  };
}
