  expect(roundContractFor("quiet-tuesday")).toMatchObject({ rounds: 12, maxTicks: 24, ticksPerRound: 2 });
  expect(roundContractFor("dinner-rush")).toMatchObject({ rounds: 12, maxTicks: 24, ticksPerRound: 2 });
