  async captureTrace(options: {
    runKind: 'live' | 'synthetic' | 'benchmark';
    additionalEvents?: Array<Event & { round: number }>;
  }): Promise<ArenaTraceV3> {
    if (!options.runKind) {
      throw new Error('runKind is required');
    }

    const events = this.getRecordedEvents();
    const initialState = this.getStateAtTick(0);

    // Merge additional events - this is where we'll handle the round stamping
    const allEvents = [...events];
    if (options.additionalEvents) {
      allEvents.push(...options.additionalEvents);
    }

    const trace: ArenaTraceV3 = {
      version: 'v3',
      runKind: options.runKind,
      episode : this.episodeId || 'unknown',
      seed: this.seed || 0,
      envVersion: this.envVersion || 'unknown',
      contractVersion: 'v3',
      initialState,
      events: allEvents,
      replay: this.getReplayRecord(),
      terminal: this.getTerminalState(),
      // sessionId only if provided
    };

    // Validate the trace
    const validation = validateArenaTraceV3(trace);
    if (!validation.valid) {
      throw new Error(`Invalid trace: ${validation.errors.join(', ')}`);
    }

    return trace;
  }
}
