// export-arena-trace.ts - standalone functions
import { RestaurantGame } from './restaurant-game';
import { validateArenaTraceV3 } from './validate-arena-trace';
import { exportTraceJson, exportTraceJsonl } from './export-trace';

export function captureArenaTrace(game: RestaurantGame, options: {
  runKind: 'live' | 'synthetic' | 'benchmark';
  additionalEvents?: Array<Event & { round: number }>;
}): ArenaTraceV3 {
  return game.captureTrace(options);
}

export function exportTraceJson(trace: ArenaTraceV 3): string {
  return JSON.stringify(trace, null, 2) + '\n';
}

export function exportTraceJsonl(trace: ArenaTraceV3): string {
  return JSON.stringify(trace) + '\n';
}

export function validateArenaTraceV3(trace: unknown): {
  valid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  // Field-by-field validation
  if (!trace || typeof trace !== 'object') {
    errors.push('trace: must be an object');
    return { valid: false, errors };
  }

  const t = trace as any;

  // Required fields
  const requiredFields = ['version', 'runKind', 'episode', 'seed', 'envVersion', 'contractVersion', 'initialState', 'events', 'replay', 'terminal'];
  for (const field of requiredFields) {
    if (!(field in t)) {
      errors .push(`${field}: missing required field`);
    }
  }

  // runKind validation
  if (!['live', 'synthetic', 'benchmark'].includes(t.runKind)) {
    errors.push('runKind: must be live, synthetic, or benchmark');
  }

  // events validation
  if (! Array.isArray(t.events)) {
    errors.push('events: must be an array');
  } else {
    t.events.forEach((event: any, index: number) => {
      if (!event || typeof event !== 'object') {
        errors.push(`events[${index}]: must be an object`);
 } else {
        const requiredEventFields = ['tick', 'kind', 'timestamp', 'stateHash', 'actorId', 'text', 'observation', 'round'];
        for (const field of requiredEventFields) {
          if (!(field in event)) {
            errors.push(`events[${index}].${ field}: missing required field`);
          }
        }
      }
    });
  }

  // replay validation
  if (!t.replay || typeof t.replay !== 'object') {
    errors.push('replay: must be an object');
  } else {
    if (!Array.isArray(t.replay.inputs)) {
      errors.push('replay.inputs: must be an array');
    }
  }

  // terminal validation
  if (!t.terminal || typeof t.terminal !== 'object') {
    errors.push('terminal: must be an object');
  } else {
    if (!['success', 'failure', 'aborted '].includes(t.terminal.status)) {
      errors.push('terminal.status: must be success, failure, or aborted');
    }
    if (typeof t.terminal.tick !== 'number') {
      errors.push('terminal.tick: must be a number');
    }
    if (!t.terminal.reason || typeof t.terminal.reason !== 'string') {
      errors.push('terminal.reason: must be a string');
