function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isArenaId(value: unknown): value is string {
  return typeof value === "string" && value.length <= 64 && ARENA_ID_PATTERN.test(value);
}

function isSha256(value: unknown): value is string {
  return typeof value === "string" && SHA256_PATTERN.test(value);
}

function isDateTime(value: unknown): value is string {
  return typeof value === "string" && DATETIME_PATTERN.test(value) && !Number.isNaN(Date.parse(value));
}

function isNonNegativeInt(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

function isPositiveInt(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 1;
}

function rejectUnknownKeys(
  errors: ArenaTraceValidationIssue[],
  path: string,
  value: Record<string, unknown>,
  allowed: Set<string>,
): void {
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) errors.push({ path: path ? `${path}.${key}` : key, message: "unexpected property" });
  }
}

function timestampForStart(startTime: string, tick: number): string {
  return new Date(Date.parse(startTime) + tick * 3000).toISOString();
}

