    seed: state.seed,
    envVersion: options.envVersion ?? ARENA_ENV_VERSION,
    contractVersion: TRACE_V3_CONTRACT_VERSION,
    runKind: options.runKind,
    initialState: game.getInitialState(),
    events: additionalEvents.length > 0 ? [...baseEvents, ...additionalEvents] : baseEvents,
    replay: structuredClone(game.getReplayRecord()),
    terminal: structuredClone(game.getTerminalStatus()),
    deletion: {
      requestId: options.deletion?.requestId !== undefined ? options.deletion.requestId : null,
      status: options.deletion?.status ?? "retained",
    },
  };
  if (options.sessionId !== undefined) {
    const { version, episodeId, ...rest } = trace;
    return { version, episodeId, sessionId: options.sessionId, ...rest };
  }
  return trace;
}

/** Pretty JSON export of a v3 trace, with float fields spelled as decimals. */
export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
  return serializeJson(trace, true, false) ?? "null";
}

/**
 * JSONL export: a header line (the trace without `events`) followed by one
 * compact JSON object per event.
 */
export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const { events, ...header } = trace;
  return [JSON.stringify(header), ...events.map((event) => JSON.stringify(event))].join("\n");
}

export function validateArenaTraceV3(value: unknown): ArenaTraceValidationResult {
  const errors: ArenaTraceValidationIssue[] = [];
  if (!isRecord(value)) {
    return { valid: false, errors: [{ path: "", message: "trace must be an object" }] };
  }
  rejectUnknownKeys(errors, "", value, ROOT_KEYS);

  if (value.version !== TRACE_V3_VERSION) {
    errors.push({ path: "version", message: `must be ${TRACE_V3_VERSION}` });
  }
  if (!isArenaId(value.episodeId)) {
    errors.push({ path: "episodeId", message: "must be a valid arena id" });
  }
  if (value.sessionId !== undefined && !isArenaId(value.sessionId)) {
    errors.push({ path: "sessionId", message: "must be a valid arena id" });
  }
  if (!isNonNegativeInt(value.seed)) {
    errors.push({ path: "seed", message: "must be a non-negative integer" });
  }
  if (typeof value.envVersion !== "string" || value.envVersion.length < 1) {
    errors.push({ path: "envVersion", message: "must be a non-empty string" });
  }
  if (value.contractVersion !== TRACE_V3_CONTRACT_VERSION) {
    errors.push({ path: "contractVersion", message: `must be ${TRACE_V3_CONTRACT_VERSION}` });
  }
  if (!RUN_KINDS.has(value.runKind as string)) {
    errors.push({ path: "runKind", message: 'must be "live", "synthetic", or "benchmark"' });
  }

  validateInitialState(errors, "initialState", value.initialState);
  validateEvents(errors, value.events);
  validateDeletion(errors, value.deletion);
  validateReplay(errors, value.replay);
  validateTerminal(errors, value.terminal);

  return { valid: errors.length === 0, errors };
}

function validateInitialState(errors: ArenaTraceValidationIssue[], path: string, value: unknown): void {
  if (!isRecord(value)) {
    errors.push({ path, message: "must be an object" });
    return;
  }
  rejectUnknownKeys(errors, path, value, STATE_KEYS);
  if (value.version !== "restaurant-arena/v1") {
    errors.push({ path: `${path}.version`, message: 'must be "restaurant-arena/v1"' });
  }
  if (!isNonNegativeInt(value.seed)) {
    errors.push({ path: `${path}.seed`, message: "must be a non-negative integer" });
  }

  if (!isRecord(value.episode)) {
    errors.push({ path: `${path}.episode`, message: "must be an object" });
  } else {
    rejectUnknownKeys(errors, `${path}.episode`, value.episode, EPISODE_KEYS);
    if (!isArenaId(value.episode.id)) errors.push({ path: `${path}.episode.id`, message: "must be a valid arena id" });
    if (value.episode.phase !== "active" && value.episode.phase !== "complete") {
      errors.push({ path: `${path}.episode.phase`, message: 'must be "active" or "complete"' });
    }
    if (!isNonNegativeInt(value.episode.tick)) errors.push({ path: `${path}.episode.tick`, message: "must be a non-negative integer" });
    if (!isPositiveInt(value.episode.maxTicks)) errors.push({ path: `${path}.episode.maxTicks`, message: "must be an integer >= 1" });
  }

  if (!isRecord(value.clock)) {
    errors.push({ path: `${path}.clock`, message: "must be an object" });
  } else {
    rejectUnknownKeys(errors, `${path}.clock`, value.clock, CLOCK_KEYS);
    if (!isNonNegativeInt(value.clock.minute)) errors.push({ path: `${path}.clock.minute`, message: "must be a non-negative integer" });
    if (!isPositiveInt(value.clock.speed)) errors.push({ path: `${path}.clock.speed`, message: "must be an integer >= 1" });
  }

  if (!Array.isArray(value.tables)) {
    errors.push({ path: `${path}.tables`, message: "must be an array" });
  } else {
    value.tables.forEach((table, index) => {
      const tablePath = `${path}.tables[${index}]`;
      if (!isRecord(table)) {
        errors.push({ path: tablePath, message: "must be an object" });
        return;
      }
      rejectUnknownKeys(errors, tablePath, table, TABLE_KEYS);
      if (!isArenaId(table.id)) errors.push({ path: `${tablePath}.id`, message: "must be a valid arena id" });
      if (!isPositiveInt(table.seats)) errors.push({ path: `${tablePath}.seats`, message: "must be an integer >= 1" });
      if (table.status !== "empty" && table.status !== "occupied") {
        errors.push({ path: `${tablePath}.status`, message: 'must be "empty" or "occupied"' });
      }
      if (table.orderId !== undefined && !isArenaId(table.orderId)) {
        errors.push({ path: `${tablePath}.orderId`, message: "must be a valid arena id" });
      }
    });
  }

  if (!Array.isArray(value.orders)) {
    errors.push({ path: `${path}.orders`, message: "must be an array" });
  } else {
    value.orders.forEach((order, index) => {
      const orderPath = `${path}.orders[${index}]`;
      if (!isRecord(order)) {
        errors.push({ path: orderPath, message: "must be an object" });
        return;
      }
      rejectUnknownKeys(errors, orderPath, order, ORDER_KEYS);
      if (!isArenaId(order.id)) errors.push({ path: `${orderPath}.id`, message: "must be a valid arena id" });
      if (order.tableId !== undefined && !isArenaId(order.tableId)) {
        errors.push({ path: `${orderPath}.tableId`, message: "must be a valid arena id" });
      }
      if (!Array.isArray(order.items) || order.items.some((item) => typeof item !== "string" || item.length < 1)) {
        errors.push({ path: `${orderPath}.items`, message: "must be an array of non-empty strings" });
      }
      if (!ORDER_STATUSES.has(order.status as string)) {
        errors.push({ path: `${orderPath}.status`, message: "must be a valid order status" });
      }
      if (order.allergy !== undefined && (typeof order.allergy !== "string" || order.allergy.length < 1)) {
        errors.push({ path: `${orderPath}.allergy`, message: "must be a non-empty string" });
      }
      if (order.priority !== "normal" && order.priority !== "high") {
        errors.push({ path: `${orderPath}.priority`, message: 'must be "normal" or "high"' });
      }
    });
  }

  if (!isRecord(value.inventory)) {
    errors.push({ path: `${path}.inventory`, message: "must be an object" });
  } else {
    for (const [item, count] of Object.entries(value.inventory)) {
      if (!Number.isInteger(count) || (count as number) < 0) {
        errors.push({ path: `${path}.inventory.${item}`, message: "must be a non-negative integer" });
      }
    }
  }

  if (!Array.isArray(value.equipment)) {
    errors.push({ path: `${path}.equipment`, message: "must be an array" });
  } else {
    value.equipment.forEach((item, index) => {
      const itemPath = `${path}.equipment[${index}]`;
      if (!isRecord(item)) {
        errors.push({ path: itemPath, message: "must be an object" });
        return;
      }
      rejectUnknownKeys(errors, itemPath, item, EQUIPMENT_KEYS);
      if (!isArenaId(item.id)) errors.push({ path: `${itemPath}.id`, message: "must be a valid arena id" });
      if (!EQUIPMENT_KINDS.has(item.kind as string)) errors.push({ path: `${itemPath}.kind`, message: 'must be "oven" or "warming_shelf"' });
      if (!EQUIPMENT_STATUSES.has(item.status as string)) errors.push({ path: `${itemPath}.status`, message: "must be a valid equipment status" });
      if (item.safetyThreshold !== undefined && typeof item.safetyThreshold !== "number") {
        errors.push({ path: `${itemPath}.safetyThreshold`, message: "must be a number" });
      }
      if (item.reading !== undefined && typeof item.reading !== "number") {
        errors.push({ path: `${itemPath}.reading`, message: "must be a number" });
      }
    });
  }

  if (!Array.isArray(value.workers)) {
    errors.push({ path: `${path}.workers`, message: "must be an array" });
  } else {
    value.workers.forEach((worker, index) => {
      const workerPath = `${path}.workers[${index}]`;
      if (!isRecord(worker)) {
        errors.push({ path: workerPath, message: "must be an object" });
        return;
      }
      rejectUnknownKeys(errors, workerPath, worker, WORKER_KEYS);
      if (!isArenaId(worker.id)) errors.push({ path: `${workerPath}.id`, message: "must be a valid arena id" });
      if (!TRACE_ROLES.has(worker.role as string)) errors.push({ path: `${workerPath}.role`, message: "must be a valid role" });
      if (typeof worker.load !== "number" || worker.load < 0 || worker.load > 1) {
        errors.push({ path: `${workerPath}.load`, message: "must be a number between 0 and 1" });
      }
      if (!WORKER_LOCATIONS.has(worker.location as string)) {
        errors.push({ path: `${workerPath}.location`, message: "must be a valid worker location" });
      }
      if (worker.lastAction !== undefined && typeof worker.lastAction !== "string") {
        errors.push({ path: `${workerPath}.lastAction`, message: "must be a string" });
      }
    });
  }

  if (value.emergency !== undefined) {
    if (!isRecord(value.emergency)) {
      errors.push({ path: `${path}.emergency`, message: "must be an object" });
    } else {
      rejectUnknownKeys(errors, `${path}.emergency`, value.emergency, EMERGENCY_KEYS);
      if (value.emergency.kind !== "oven_failure") {
        errors.push({ path: `${path}.emergency.kind`, message: 'must be "oven_failure"' });
      }
      if (typeof value.emergency.active !== "boolean") {
        errors.push({ path: `${path}.emergency.active`, message: "must be a boolean" });
      }
      if (!isNonNegativeInt(value.emergency.startedAt)) {
        errors.push({ path: `${path}.emergency.startedAt`, message: "must be a non-negative integer" });
      }
    }
  }

  if (value.seatingHeld !== undefined && typeof value.seatingHeld !== "boolean") {
    errors.push({ path: `${path}.seatingHeld`, message: "must be a boolean" });
  }

  if (typeof value.reputation !== "number" || value.reputation < 0 || value.reputation > 100) {
    errors.push({ path: `${path}.reputation`, message: "must be a number between 0 and 100" });
  }

  if (!isRecord(value.outcomes)) {
    errors.push({ path: `${path}.outcomes`, message: "must be an object" });
  } else {
    rejectUnknownKeys(errors, `${path}.outcomes`, value.outcomes, OUTCOME_KEYS);
    for (const key of ["cash", "satisfaction", "waste", "waitTime", "coordination", "correctionUptake"] as const) {
      if (typeof value.outcomes[key] !== "number") {
        errors.push({ path: `${path}.outcomes.${key}`, message: "must be a number" });
      }
    }
    for (const key of ["completed", "safeOrders"] as const) {
      if (!isNonNegativeInt(value.outcomes[key])) {
        errors.push({ path: `${path}.outcomes.${key}`, message: "must be a non-negative integer" });
      }
    }
  }
}

function validateEvents(errors: ArenaTraceValidationIssue[], value: unknown): void {
  if (!Array.isArray(value)) {
    errors.push({ path: "events", message: "must be an array" });
    return;
  }
  value.forEach((event, index) => validateEvent(errors, `events[${index}]`, event));
}

function validateEvent(errors: ArenaTraceValidationIssue[], path: string, value: unknown): void {
  if (!isRecord(value)) {
    errors.push({ path, message: "must be an object" });
    return;
  }
  rejectUnknownKeys(errors, path, value, EVENT_KEYS);
  if (!isNonNegativeInt(value.tick)) errors.push({ path: `${path}.tick`, message: "must be a non-negative integer" });
  if (value.round !== undefined && !isPositiveInt(value.round)) {
    errors.push({ path: `${path}.round`, message: "must be an integer >= 1" });
  }
  if (!TRACE_EVENT_KINDS.has(value.kind as TraceEventKind)) {
    errors.push({ path: `${path}.kind`, message: "must be a valid trace event kind" });
  }
  if (!isDateTime(value.timestamp)) errors.push({ path: `${path}.timestamp`, message: "must be an RFC 3339 date-time" });
  if (!isSha256(value.stateHash)) errors.push({ path: `${path}.stateHash`, message: "must be a sha256:... digest" });
  if (value.actorId !== undefined && !isArenaId(value.actorId)) {
    errors.push({ path: `${path}.actorId`, message: "must be a valid arena id" });
  }
  if (value.role !== undefined && !TRACE_ROLES.has(value.role as string)) {
    errors.push({ path: `${path}.role`, message: "must be a valid role" });
  }
  if (value.targetRole !== undefined && !TRACE_ROLES.has(value.targetRole as string)) {
    errors.push({ path: `${path}.targetRole`, message: "must be a valid role" });
  }
  if (value.checkpointId !== undefined && !isArenaId(value.checkpointId)) {
    errors.push({ path: `${path}.checkpointId`, message: "must be a valid arena id" });
  }
  if (value.model !== undefined) {
    if (!isRecord(value.model)) {
      errors.push({ path: `${path}.model`, message: "must be an object" });
    } else {
      rejectUnknownKeys(errors, `${path}.model`, value.model, MODEL_KEYS);
      if (typeof value.model.provider !== "string" || value.model.provider.length < 1) {
        errors.push({ path: `${path}.model.provider`, message: "must be a non-empty string" });
      }
      if (typeof value.model.name !== "string" || value.model.name.length < 1) {
        errors.push({ path: `${path}.model.name`, message: "must be a non-empty string" });
      }
      if (value.model.version !== undefined && (typeof value.model.version !== "string" || value.model.version.length < 1)) {
        errors.push({ path: `${path}.model.version`, message: "must be a non-empty string" });
      }
    }
  }
  if (value.requestId !== undefined && !isArenaId(value.requestId)) {
    errors.push({ path: `${path}.requestId`, message: "must be a valid arena id" });
  }
  if (
    value.idempotencyKey !== undefined &&
    (typeof value.idempotencyKey !== "string" || value.idempotencyKey.length > 130 || !IDEMPOTENCY_PATTERN.test(value.idempotencyKey))
  ) {
    errors.push({ path: `${path}.idempotencyKey`, message: "must be a valid idempotency key" });
  }
  if (value.text !== undefined && value.text !== null && typeof value.text !== "string") {
    errors.push({ path: `${path}.text`, message: "must be a string or null" });
  }
  if (value.observation !== undefined && value.observation !== null && !isRecord(value.observation)) {
    errors.push({ path: `${path}.observation`, message: "must be an object or null" });
  }
  if (value.action !== undefined && value.action !== null && !isRecord(value.action)) {
    errors.push({ path: `${path}.action`, message: "must be an object or null" });
  }
  if (value.toolResult !== undefined && value.toolResult !== null) validateToolResult(errors, `${path}.toolResult`, value.toolResult);
  if (value.outcome !== undefined && value.outcome !== null && !isRecord(value.outcome)) {
    errors.push({ path: `${path}.outcome`, message: "must be an object or null" });
  }
  if (value.correctionRationale !== undefined && value.correctionRationale !== null && typeof value.correctionRationale !== "string") {
    errors.push({ path: `${path}.correctionRationale`, message: "must be a string or null" });
  }
  if (
    value.correctionCategory !== undefined &&
    value.correctionCategory !== null &&
    !CORRECTION_CATEGORIES.has(value.correctionCategory as string)
  ) {
    errors.push({ path: `${path}.correctionCategory`, message: 'must be "safety", "priority", "quality", "pace", or null' });
  }
  if (value.changedDecisionEventId !== undefined && value.changedDecisionEventId !== null && !isArenaId(value.changedDecisionEventId)) {
    errors.push({ path: `${path}.changedDecisionEventId`, message: "must be a valid arena id or null" });
  }
  if (value.probeEventId !== undefined && value.probeEventId !== null && !isArenaId(value.probeEventId)) {
    errors.push({ path: `${path}.probeEventId`, message: "must be a valid arena id or null" });
  }
  if (value.subject !== undefined) {
    if (!isRecord(value.subject)) {
      errors.push({ path: `${path}.subject`, message: "must be an object" });
    } else {
      rejectUnknownKeys(errors, `${path}.subject`, value.subject, SUBJECT_KEYS);
      if (!SUBJECT_KINDS.has(value.subject.kind as string)) {
        errors.push({ path: `${path}.subject.kind`, message: "must be a valid subject kind" });
      }
      if (!isArenaId(value.subject.id)) errors.push({ path: `${path}.subject.id`, message: "must be a valid arena id" });
    }
  }
  if (value.payload !== undefined && value.payload !== null && !isRecord(value.payload)) {
    errors.push({ path: `${path}.payload`, message: "must be an object or null" });
  }
}

function validateToolResult(errors: ArenaTraceValidationIssue[], path: string, value: unknown): void {
  if (!isRecord(value)) {
    errors.push({ path, message: "must be an object or null" });
    return;
  }
  if (value.ok !== undefined && typeof value.ok !== "boolean") {
    errors.push({ path: `${path}.ok`, message: "must be a boolean" });
  }
  if (value.latencyMs !== undefined && (typeof value.latencyMs !== "number" || value.latencyMs < 0)) {
    errors.push({ path: `${path}.latencyMs`, message: "must be a number >= 0" });
  }
  const errorBody = value.error;
  if (errorBody !== undefined && errorBody !== null) {
    if (!isRecord(errorBody)) {
      errors.push({ path: `${path}.error`, message: "must be an object or null" });
    } else {
      if (typeof errorBody.code !== "string" || errorBody.code.length < 1) {
        errors.push({ path: `${path}.error.code`, message: "must be a non-empty string" });
      }
      if (typeof errorBody.message !== "string" || errorBody.message.length < 1) {
        errors.push({ path: `${path}.error.message`, message: "must be a non-empty string" });
      }
      if (errorBody.retryable !== undefined && typeof errorBody.retryable !== "boolean") {
        errors.push({ path: `${path}.error.retryable`, message: "must be a boolean" });
      }
    }
  }
  if (value.ok === false && (errorBody === undefined || errorBody === null || !isRecord(errorBody))) {
    errors.push({ path: `${path}.error`, message: "required when ok is false" });
  }
  if (errorBody !== undefined && errorBody !== null && isRecord(errorBody) && value.ok !== false) {
    errors.push({ path: `${path}.ok`, message: "must be false when error is present" });
  }
}

function validateDeletion(errors: ArenaTraceValidationIssue[], value: unknown): void {
  if (!isRecord(value)) {
    errors.push({ path: "deletion", message: "must be an object" });
    return;
  }
  rejectUnknownKeys(errors, "deletion", value, DELETION_KEYS);
  if (value.requestId !== null && !isArenaId(value.requestId)) {
    errors.push({ path: "deletion.requestId", message: "must be a valid arena id or null" });
  }
  if (!DELETION_STATUSES.has(value.status as string)) {
    errors.push({ path: "deletion.status", message: 'must be "retained", "requested", or "deleted"' });
  }
}

function validateTerminal(errors: ArenaTraceValidationIssue[], value: unknown): void {
  if (!isRecord(value)) {
    errors.push({ path: "terminal", message: "must be an object" });
    return;
  }
  rejectUnknownKeys(errors, "terminal", value, TERMINAL_KEYS);
  if (!TERMINAL_STATUSES.has(value.status as string)) {
    errors.push({ path: "terminal.status", message: 'must be "active", "completed", or "abandoned"' });
  }
  if (!isNonNegativeInt(value.tick)) {
    errors.push({ path: "terminal.tick", message: "must be a non-negative integer" });
  }
  if (!("reason" in value) || (value.reason !== null && typeof value.reason !== "string")) {
    errors.push({ path: "terminal.reason", message: "must be a string or null" });
  }
}

function validateReplay(errors: ArenaTraceValidationIssue[], value: unknown): void {
  if (!isRecord(value)) {
    errors.push({ path: "replay", message: "must be an object" });
    return;
  }
  rejectUnknownKeys(errors, "replay", value, REPLAY_KEYS);
  if (!TRACE_VARIATIONS.has(value.variation as string)) {
    errors.push({ path: "replay.variation", message: "must be a published shift variation" });
  }
  if (!isSha256(value.finalStateHash)) {
    errors.push({ path: "replay.finalStateHash", message: "must be a sha256:... digest" });
  }
  if (value.finalRestaurantStateHash !== undefined && !isSha256(value.finalRestaurantStateHash)) {
    errors.push({ path: "replay.finalRestaurantStateHash", message: "must be a sha256:... digest" });
  }
  if (!Array.isArray(value.inputs)) {
    errors.push({ path: "replay.inputs", message: "must be an array" });
    return;
  }
  value.inputs.forEach((input, index) => validateReplayInput(errors, `replay.inputs[${index}]`, input));
}

function validateReplayInput(errors: ArenaTraceValidationIssue[], path: string, value: unknown): void {
  if (!isRecord(value)) {
    errors.push({ path, message: "must be an object" });
    return;
  }
  if (!INPUT_KINDS.has(value.kind as string)) {
    errors.push({ path: `${path}.kind`, message: 'must be "step", "time", "envelope", or "controllers"' });
    return;
  }
  const allowed =
    value.kind === "step"
      ? STEP_INPUT_KEYS
      : value.kind === "time"
        ? TIME_INPUT_KEYS
        : value.kind === "envelope"
          ? ENVELOPE_INPUT_KEYS
          : CONTROLLER_INPUT_KEYS;
  rejectUnknownKeys(errors, path, value, allowed);
  if (!isNonNegativeInt(value.tick)) errors.push({ path: `${path}.tick`, message: "must be a non-negative integer" });
  if (!isSha256(value.stateHash)) errors.push({ path: `${path}.stateHash`, message: "must be a sha256:... digest" });
  if (value.restaurantStateHash !== undefined && !isSha256(value.restaurantStateHash)) {
    errors.push({ path: `${path}.restaurantStateHash`, message: "must be a sha256:... digest" });
  }
  if (value.kind === "step" && (typeof value.action !== "string" || value.action.length < 1)) {
    errors.push({ path: `${path}.action`, message: "must be a non-empty string" });
  }
  if (value.kind === "envelope") {
    validateActionEnvelope(errors, `${path}.envelope`, value.envelope);
    if (value.telemetry !== undefined && !isRecord(value.telemetry)) {
      errors.push({ path: `${path}.telemetry`, message: "must be an object" });
    }
  }
  if (value.kind === "controllers") {
    if (!Array.isArray(value.roles) || new Set(value.roles as unknown[]).size !== value.roles.length) {
      errors.push({ path: `${path}.roles`, message: "must be an array of unique roles" });
    } else {
      value.roles.forEach((role, index) => {
        if (!TRACE_ROLES.has(role as string)) {
          errors.push({ path: `${path}.roles[${index}]`, message: "must be a valid role" });
        }
      });
    }
  }
}

function validateActionEnvelope(errors: ArenaTraceValidationIssue[], path: string, value: unknown): void {
  if (!isRecord(value)) {
    errors.push({ path, message: "must be an action envelope object" });
    return;
  }
  rejectUnknownKeys(errors, path, value, ENVELOPE_KEYS);
  if (value.version !== "restaurant-arena-action/v1") {
    errors.push({ path: `${path}.version`, message: 'must be "restaurant-arena-action/v1"' });
  }
  if (!isArenaId(value.episodeId)) errors.push({ path: `${path}.episodeId`, message: "must be a valid arena id" });
  if (!isArenaId(value.actorId)) errors.push({ path: `${path}.actorId`, message: "must be a valid arena id" });
  if (value.actorType !== "worker" && value.actorType !== "player") {
    errors.push({ path: `${path}.actorType`, message: 'must be "worker" or "player"' });
