import { RestaurantGame, type ArenaInputRecord, type EnvelopeTelemetry } from "./restaurant-game.js";
import { computeStateHash, type RestaurantArenaTraceV3 } from "./trace.js";
import type { Role } from "./types.js";

const LEGACY_ROLE = "expediter";
const CANONICAL_ROLE = "supply_lead";
const LEGACY_WORKER_ID = "worker-expediter";
const CANONICAL_WORKER_ID = "worker-supply_lead";

/**
 * Map the legacy expediter roster onto supply_lead before hashing tick-0
 * state. Role name is the only tolerated divergence; every other field —
 * including ones with no dedicated schema rule — must still match.
 */
export function canonicalizeArenaState(state: unknown): unknown {
  const clone = structuredClone(state) as Record<string, unknown>;
  if (!Array.isArray(clone.workers)) return clone;
  clone.workers = clone.workers.map((worker) => {
    if (typeof worker !== "object" || worker === null) return worker;
    const next = { ...(worker as Record<string, unknown>) };
    if (next.role === LEGACY_ROLE) next.role = CANONICAL_ROLE;
    if (next.id === LEGACY_WORKER_ID) next.id = CANONICAL_WORKER_ID;
    return next;
  });
  return clone;
}

export function applyArenaReplayInput(game: RestaurantGame, input: ArenaInputRecord, _index?: number): void {
  switch (input.kind) {
    case "step":
      game.step(input.action);
      return;
    case "time":
      game.advanceTime();
      return;
    case "envelope":
      game.stepEnvelope(input.envelope, input.telemetry as EnvelopeTelemetry | undefined);
      return;
    case "controllers":
      game.setExternalControllers(input.roles as Array<Role | "expediter">);
      return;
    default: {
      const neverKind: never = input;
      throw new Error(`unknown replay input kind: ${(neverKind as { kind: string }).kind}`);
    }
  }
}

export function replayArenaTrace(trace: RestaurantArenaTraceV3): RestaurantGame {
  const game = new RestaurantGame(trace.seed, trace.replay.variation);

  const actualInitial = canonicalizeArenaState(game.getInitialState());
  const recordedInitial = canonicalizeArenaState(trace.initialState);
  if (computeStateHash(actualInitial) !== computeStateHash(recordedInitial)) {
    throw new Error("initial state mismatch");
  }

  for (const [index, input] of trace.replay.inputs.entries()) {
    applyArenaReplayInput(game, input, index);
    const checkpoint = computeStateHash(game.checkpointState());
    if (checkpoint !== input.stateHash) {
      throw new Error(`checkpoint mismatch at input ${index}`);
    }
    if (input.restaurantStateHash !== undefined && computeStateHash(game.state()) !== input.restaurantStateHash) {
      throw new Error(`restaurant state hash mismatch at input ${index}`);
