#!/usr/bin/env bun
/**
 * Capture the frozen dinner-rush benchmark trace and write (or check)
 * contracts/fixtures/restaurant-arena-trace-v3.json.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { RestaurantGame } from "../src/games/restaurant-arena/restaurant-game.js";
import {
  captureArenaTrace,
  exportTraceJson,
  type RestaurantArenaTraceV3,
} from "../src/games/restaurant-arena/trace.js";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const FIXTURE_PATH = join(ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");
const BENCHMARK_SEED = 218220;
const BENCHMARK_VARIATION = "dinner-rush";
const BENCHMARK_EPISODE_ID = "dinner-rush-benchmark-218220";
const BENCHMARK_START_TIME = "2026-09-05T18:00:00.000Z";

function captureBenchmarkTrace(): RestaurantArenaTraceV3 {
  const game = new RestaurantGame(BENCHMARK_SEED, BENCHMARK_VARIATION);
  game.step("sim_start");
  for (let i = 0; i < 10; i++) game.step("tick");
  game.step("verify_substitution");
  for (let i = 0; i < 14; i++) game.step("tick");
  return captureArenaTrace(game, {
    runKind: "benchmark",
    episodeId: BENCHMARK_EPISODE_ID,
    startTime: BENCHMARK_START_TIME,
  });
}

function tracesMatch(actual: RestaurantArenaTraceV3, expected: unknown): boolean {
  return JSON.stringify(actual) === JSON.stringify(expected);
}

const check = process.argv.includes("--check");
const captured = captureBenchmarkTrace();

if (check) {
  const existing = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));
  if (!tracesMatch(captured, existing)) {
    console.error("Fixture is stale");
    process.exit(1);
  }
  console.log("Fixture is current");
  process.exit(0);
}

writeFileSync(FIXTURE_PATH, `${exportTraceJson(captured)}\n`);
console.log(`Wrote ${FIXTURE_PATH}`);

#!/usr/bin/env bun
/**
 * Load a restaurant-arena-trace-v3 JSON or JSONL file, validate it, and
 * natively replay it. Prints "Native replay passed" on success.
 */

import { readFileSync } from "node:fs";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";
import {
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
} from "../src/games/restaurant-arena/trace.js";

function usage(): never {
  console.error("Usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
  process.exit(2);
}

function loadTrace(path: string): RestaurantArenaTraceV3 {
  const text = readFileSync(path, "utf8");
  if (path.endsWith(".jsonl")) {
    const lines = text.split(/\r?\n/).filter((line) => line.trim().length > 0);
    if (lines.length === 0) throw new Error("empty JSONL trace");
    const header = JSON.parse(lines[0]!) as Record<string, unknown>;
    const events = lines.slice(1).map((line) => JSON.parse(line));
    return { ...header, events } as RestaurantArenaTraceV3;
  }
  return JSON.parse(text) as RestaurantArenaTraceV3;
}

const path = process.argv[2];
if (!path) usage();

try {
  const trace = loadTrace(path);
  const validation = validateArenaTraceV3(trace);
  if (!validation.valid) {
    for (const error of validation.errors) {
      console.error(`${error.path}: ${error.message}`);
    }
    process.exit(1);
  }
  replayArenaTrace(trace);
  console.log("Native replay passed");
} catch (error) {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
}

