import { describe, expect, it } from "bun:test";
import { RestaurantGame } from "./restaurant-game.js";
import { applyArenaReplayInput, replayArenaTrace } from "./replay.js";
import {
  captureArenaTrace,
  exportTraceJson,
  exportTraceJsonl,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
  type TraceV3Event,
} from "./trace.js";

function playDinnerRush(seed = 218220): RestaurantGame {
  const game = new RestaurantGame(seed, "dinner-rush");
  game.step("sim_start");
  for (let i = 0; i < 10; i++) game.step("tick");
  game.step("verify_substitution");
  for (let i = 0; i < 14; i++) game.step("tick");
  return game;
}

function extraEvent(tick: number, text: string): TraceV3Event {
  return {
    tick,
    kind: "message",
    timestamp: "2026-09-05T18:00:00.000Z",
    stateHash: "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
    actorId: "player",
    text,
  };
}

describe("restaurant-arena-trace-v3 capture", () => {
  it("game.captureTrace delegates to captureArenaTrace with the same options", () => {
    const game = playDinnerRush();
    const options = { runKind: "live" as const, sessionId: "session-overlay-1" };
    expect(game.captureTrace(options)).toEqual(captureArenaTrace(game, options));
  });

  it("captures tick-0 state, the event journal, replay inputs, and the full terminal record", () => {
    const game = playDinnerRush();
    const trace = captureArenaTrace(game, { runKind: "benchmark", episodeId: "dinner-rush-benchmark-218220" });
    expect(trace.version).toBe("restaurant-arena-trace/v3");
    expect(trace.runKind).toBe("benchmark");
    expect(trace.initialState).toEqual(game.getInitialState());
    expect(trace.events).toEqual(game.getRecordedEvents());
    expect(trace.replay).toEqual(game.getReplayRecord());
    expect(trace.terminal).toEqual(game.getTerminalStatus());
    expect(trace.terminal).toEqual({ status: "completed", tick: 24, reason: "episode_complete" });
    expect(trace.deletion).toEqual({ requestId: null, status: "retained" });
  });

  it("identifying the session a trace came from (#281)", () => {
    const game = playDinnerRush();
    const first = captureArenaTrace(game, { runKind: "live", sessionId: "session-a" });
    const second = captureArenaTrace(game, { runKind: "live", sessionId: "session-b" });
    expect(first.episodeId).toBe(second.episodeId);
    expect(first.sessionId).toBe("session-a");
    expect(second.sessionId).toBe("session-b");
    expect(first.sessionId).not.toBe(second.sessionId);
    const omitted = captureArenaTrace(game, { runKind: "live" });
    expect(omitted.sessionId).toBeUndefined();
  });

  it("stamps additionalEvents with the round their tick falls in", () => {
    const game = playDinnerRush();
    const trace = captureArenaTrace(game, {
      runKind: "synthetic",
      additionalEvents: [extraEvent(0, "note-0"), extraEvent(8, "note-8"), extraEvent(3, "note-3")],
    });
    const notes = trace.events.filter((event) => event.text?.startsWith("note-"));
    expect(notes).toEqual([
      expect.objectContaining({ tick: 0, round: 1, text: "note-0" }),
      expect.objectContaining({ tick: 8, round: 4, text: "note-8" }),
      expect.objectContaining({ tick: 3, round: 2, text: "note-3" }),
    ]);
  });

  it("replaces the journal wholesale when events are passed", () => {
    const game = playDinnerRush();
    const replacement = [extraEvent(0, "only")];
    const trace = captureArenaTrace(game, { runKind: "live", events: replacement });
    expect(trace.events).toHaveLength(1);
    expect(trace.events[0]?.text).toBe("only");
  });

  it("rewrites event timestamps from startTime", () => {
    const game = playDinnerRush();
    const trace = captureArenaTrace(game, { runKind: "benchmark", startTime: "2026-09-05T18:00:00.000Z" });
    expect(trace.events[0]?.timestamp).toBe("2026-09-05T18:00:00.000Z");
    const tick1 = trace.events.find((event) => event.tick === 1);
    expect(tick1?.timestamp).toBe("2026-09-05T18:00:03.000Z");
  });
});

describe("restaurant-arena-trace-v3 export and validation", () => {
  it("exports schema-valid JSON and JSONL", () => {
    const trace = captureArenaTrace(playDinnerRush(), { runKind: "live" });
    const parsed = JSON.parse(exportTraceJson(trace));
    expect(validateArenaTraceV3(parsed)).toEqual({ valid: true, errors: [] });

    const jsonl = exportTraceJsonl(trace);
    const lines = jsonl.trim().split("\n");
    expect(lines.length).toBe(trace.events.length + 1);
    expect(JSON.parse(lines[0]!)).toMatchObject({ version: trace.version, replay: trace.replay });
    expect(JSON.parse(lines[0]!).events).toBeUndefined();
  });

  it("rejects malformed records field by field", () => {
    const trace = captureArenaTrace(playDinnerRush(), { runKind: "live" });
    const cases: Array<[string, RestaurantArenaTraceV3]> = [
      ["runKind", { ...trace, runKind: "demo" as RestaurantArenaTraceV3["runKind"] }],
      ["version", { ...trace, version: "restaurant-arena-trace/v2" as RestaurantArenaTraceV3["version"] }],
      ["episodeId", { ...trace, episodeId: "" }],
      ["sessionId", { ...trace, sessionId: "bad id" }],
      ["seed", { ...trace, seed: -1 }],
      ["envVersion", { ...trace, envVersion: "" }],
      ["contractVersion", { ...trace, contractVersion: "nope" as RestaurantArenaTraceV3["contractVersion"] }],
      ["terminal.status", { ...trace, terminal: { ...trace.terminal, status: "won" as "completed" } }],
      ["terminal.tick", { ...trace, terminal: { ...trace.terminal, tick: -4 } }],
      ["terminal.reason", { ...trace, terminal: { ...trace.terminal, reason: 1 as unknown as string } }],
      ["deletion.status", { ...trace, deletion: { requestId: null, status: "kept" as "retained" } }],
      ["replay.finalStateHash", { ...trace, replay: { ...trace.replay, finalStateHash: "not-a-hash" } }],
      ["events[0].kind", { ...trace, events: [{ ...trace.events[0]!, kind: "nope" as TraceV3Event["kind"] }] }],
      ["events[0].stateHash", { ...trace, events: [{ ...trace.events[0]!, stateHash: "sha256:zz" }] }],
    ];
    for (const [path, malformed] of cases) {
      const result = validateArenaTraceV3(malformed);
      expect(result.valid).toBe(false);
      expect(result.errors.some((error) => error.path === path), path).toBe(true);
    }
  });
});

describe("native replayArenaTrace", () => {
  it("returns the rebuilt live game when every hash and the terminal record match", () => {
    const game = playDinnerRush();
    const trace = game.captureTrace({ runKind: "live" });
    const replayed = replayArenaTrace(trace);
    expect(replayed).toBeInstanceOf(RestaurantGame);
    expect(replayed.getTerminalStatus()).toEqual(trace.terminal);
    expect(replayed.checkpointState()).toEqual(game.checkpointState());
    expect(replayed.state()).toEqual(game.state());
  });

  it("throws when any part of the recorded terminal disagrees", () => {
    const trace = playDinnerRush().captureTrace({ runKind: "live" });
    expect(() => replayArenaTrace({ ...trace, terminal: { ...trace.terminal, reason: "tampered" } })).toThrow("terminal mismatch");
    expect(() => replayArenaTrace({ ...trace, terminal: { ...trace.terminal, tick: 0 } })).toThrow("terminal mismatch");
    expect(() => replayArenaTrace({ ...trace, terminal: { ...trace.terminal, status: "abandoned" } })).toThrow("terminal mismatch");
  });

  it("throws when initialState is altered in a field with no dedicated schema rule", () => {
    const trace = playDinnerRush().captureTrace({ runKind: "live" });
    const initialState = structuredClone(trace.initialState) as { outcomes: { cash: number } };
    initialState.outcomes.cash = 99;
    expect(() => replayArenaTrace({ ...trace, initialState })).toThrow("initial state mismatch");
  });

  it("accepts a historical roster that still names the expediter worker", () => {
    const trace = playDinnerRush().captureTrace({ runKind: "live" });
    const initialState = structuredClone(trace.initialState) as {
      workers: Array<{ id: string; role: string }>;
    };
    for (const worker of initialState.workers) {
      if (worker.role === "supply_lead") {
        worker.role = "expediter";
        worker.id = "worker-expediter";
      }
    }
    const replayed = replayArenaTrace({ ...trace, initialState });
    expect(replayed.getTerminalStatus()).toEqual(trace.terminal);
  });

  it("throws when a checkpoint hash disagrees", () => {
    const trace = playDinnerRush().captureTrace({ runKind: "live" });
    const inputs = structuredClone(trace.replay.inputs);
    inputs[0]!.stateHash = "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
    expect(() => replayArenaTrace({ ...trace, replay: { ...trace.replay, inputs } })).toThrow("checkpoint mismatch");
  });

  it("applyArenaReplayInput replays a recorded step", () => {
    const source = playDinnerRush();
    const trace = source.captureTrace({ runKind: "live" });
    const game = new RestaurantGame(trace.seed, trace.replay.variation);
    applyArenaReplayInput(game, trace.replay.inputs[0]!, 0);
    expect(game.view().sim.started).toBe(true);
  });
});

